122	/**
123	 * A policy the office has written: the {@link Coverage} it was written over and
124	 * the {@link PayoutCap} it was written under.
125	 *
126	 * Settling an incident against the policy is this policy's decision, not the
127	 * protocol's, and all it decides is how the three parties to a settlement meet:
128	 * the coverage says which covered item a reported damage is settled on, the
129	 * {@link ClaimPolicy} says what that one damage earns, and the cap says how much
130	 * of it is actually paid. So the deductible is borne once per damage reported
131	 * and the cap is consumed in the order the damages are reported.
132	 */
133	public class Policy {
134	
135	    private final Coverage coverage;
136	    private final PayoutCap payoutCap;
137	
138	    /**
139	     * The office writes a policy over the items a customer brings: what it
140	     * insures them for is the {@link PriceList}'s to state, and the cap that
141	     * insurance sum earns is the cap's own rule. Premium modifiers are no part
142	     * of it, which is why the policy is written from the covered items and never
143	     * from the premium quoted for them.
144	     */
145	    public static Policy covering(List<InsuredItem> insuredItems, PriceList priceList) {
146	        return new Policy(Coverage.of(insuredItems),
147	                PayoutCap.forInsuranceSum(priceList.insuranceSum(insuredItems)));
148	    }
149	
150	    private Policy(Coverage coverage, PayoutCap payoutCap) {
151	        this.coverage = coverage;
152	        this.payoutCap = payoutCap;
153	    }
154	
155	    /**
156	     * What the office pays for one reported incident: every damage reimbursed on
157	     * its own terms, the total limited to the cap the policy has left.
158	     */
159	    public BigDecimal settle(List<Damage> damages, ClaimPolicy claimPolicy) {
160	        BigDecimal paid = BigDecimal.ZERO;
161	        for (Damage damage : damages) {
162	            paid = paid.add(payoutCap.pay(claimPolicy.reimbursementFor(
163	                    damage.amount(), coverage.itemDamagedBy(damage))));
164	        }
165	        return paid;
166	    }
167	
168	    public BigDecimal remainingCap() {
169	        return payoutCap.remaining();
170	    }
171	}
172	/**
173	 * An item a policy covers, as the office records it.
174	 *
175	 * The office reads the recorded facts to classify the item's risk, so the
176	 * classifications live here with the facts they read, while what each risk
177	 * costs is the premium rules' business in {@link PremiumPolicy}. The
178	 * enchantment level carries more than one such classification: the premium
179	 * rules surcharge a high enchantment from level 5 up, and the claim rules have
180	 * their own, higher threshold, so each threshold is named for the rule it
181	 * serves rather than sharing one vague "enchanted" predicate.
182	 */
183	public record InsuredItem(String type, boolean cursed, int enchantment) {
184	
185	    private static final int HIGH_ENCHANTMENT_LEVEL = 5;
186	    private static final int UNRULY_ENCHANTMENT_LEVEL = 8;
187	
188	    /**
189	     * The office counts an item as highly enchanted, and so as carrying a risk
190	     * worth a surcharge, from enchantment level 5 up.
191	     */
192	    public boolean isHighlyEnchanted() {
193	        return enchantment >= HIGH_ENCHANTMENT_LEVEL;
194	    }
195	
196	    /**
197	     * From enchantment level 8 up the office considers an item too unruly for
198	     * its damage to be reimbursed in full. What such a damage earns instead is
199	     * the claim rules' clause to state, in {@link ClaimPolicy}.
200	     */
201	    public boolean isTooUnrulyToReimburseInFull() {
202	        return enchantment >= UNRULY_ENCHANTMENT_LEVEL;
203	    }
204	}
