207	/**
208	 * The limit on everything a policy will ever pay out, and how much of it is
209	 * left. The office caps a policy at twice the insurance sum of the items it
210	 * covers.
211	 *
212	 * What the cap is worth and what it has left are one decision revised on its
213	 * own schedule: a revision to the multiple, or one that let the cap replenish,
214	 * is this cap's business and touches no claim rule. Premium modifiers are no
215	 * part of it, which is why a cap is opened from an insurance sum and never from
216	 * a premium.
217	 */
218	class PayoutCap {
219	
220	    private static final BigDecimal CAP_MULTIPLE_OF_INSURANCE_SUM = new BigDecimal("2");
221	
222	    private BigDecimal remaining;
223	
224	    static PayoutCap forInsuranceSum(BigDecimal insuranceSum) {
225	        return new PayoutCap(insuranceSum.multiply(CAP_MULTIPLE_OF_INSURANCE_SUM));
226	    }
227	
228	    private PayoutCap(BigDecimal remaining) {
229	        this.remaining = remaining;
230	    }
231	
232	    /** Pays what the cap still allows of a desired payout and consumes that much of it. */
233	    BigDecimal pay(BigDecimal desiredPayout) {
234	        BigDecimal paid = desiredPayout.min(remaining);
235	        remaining = remaining.subtract(paid);
236	        return paid;
237	    }
238	
239	    BigDecimal remaining() {
240	        return remaining;
241	    }
242	}

