 62	/**
 63	 * What a policy covers: the items the office recorded when it wrote the policy,
 64	 * able to say which of them a reported damage is settled on.
 65	 *
 66	 * Reading a damage report against the covered items is a decision of its own,
 67	 * revised on its own schedule and quite apart from what one damage earns or what
 68	 * the cap allows. Two pending revisions are this coverage's alone: counting a
 69	 * policy's several items of one kind against the damages reported for that kind,
 70	 * and refusing a damage that names a kind the policy does not cover. Neither
 71	 * touches the claim rules or the cap.
 72	 */
 73	record Coverage(List<InsuredItem> insuredItems) {
 74	
 75	    static Coverage of(List<InsuredItem> insuredItems) {
 76	        return new Coverage(List.copyOf(insuredItems));
 77	    }
 78	
 79	    /**
 80	     * The covered item whose terms a reported damage is settled on: the office
 81	     * looks the reported kind of item up among the items it covers, and the
 82	     * claim rules read the clauses from it. A damage naming a kind of item the
 83	     * coverage does not include is no claim the office will settle.
 84	     *
 85	     * The office matches by the kind of item reported, which is all a single
 86	     * covered item of a kind needs. Counting several items of one kind against
 87	     * the damages reported for that kind is a separate decision the office has
 88	     * not been asked to make yet.
 89	     */
 90	    InsuredItem itemDamagedBy(Damage damage) {
 91	        for (InsuredItem insuredItem : insuredItems) {
 92	            if (insuredItem.type().equals(damage.itemType())) {
 93	                return insuredItem;
 94	            }
 95	        }
 96	        throw new IllegalArgumentException(
 97	                "the policy does not cover a " + damage.itemType());
 98	    }
 99	}
100	/**
101	 * The customer a scenario is about, as the office knows them: their standing
102	 * with the MHPCO at the moment a premium is quoted.
103	 *
104	 * Both facts here are the office's view of its relationship with this customer
105	 * rather than of the items insured, so this is also where the office decides
106	 * what that relationship entitles the customer to: whether they count as
107	 * long-standing, and whether this contract is a follow-up. The rates those
108	 * entitlements earn are the premium rules' business, in {@link PremiumPolicy}.
109	 */
110	public record Customer(int yearsWithMHPCO, int contractsAlreadyHeld) {
111	
112	    private static final int LOYALTY_YEARS = 2;
113	
114	    /**
115	     * The office counts a customer as long-standing from 2 years of business
116	     * with the MHPCO up; a newer customer earns no loyalty.
117	     */
118	    public boolean isLongStanding() {
119	        return yearsWithMHPCO >= LOYALTY_YEARS;
120	    }
121	
122	    /**
123	     * Every contract after the customer's first is a follow-up, however long
124	     * they have been with the office.
125	     */
126	    public boolean holdsFollowUpContract() {
127	        return contractsAlreadyHeld > 0;
128	    }
129	}
