138	/**
139	 * The MHPCO rounds every amount to whole G in its own favor. One rule, read in
140	 * the direction the money moves: a fraction of a G the customer owes the office
141	 * is rounded up, a fraction the office owes the customer is rounded down. The
142	 * office never loses the fraction.
143	 *
144	 * Intermediate amounts during a calculation stay exact fractions; only a final
145	 * charge or payment is rounded.
146	 */
147	final class InOfficesFavor {
148	
149	    private static final int WHOLE_G = 0;
150	
151	    private InOfficesFavor() {
152	    }
153	
154	    /** What the customer owes the office, rounded up: the fraction favors the office. */
155	    static BigDecimal charge(BigDecimal amount) {
156	        return amount.setScale(WHOLE_G, RoundingMode.CEILING);
157	    }
158	
159	    /** What the office owes the customer, rounded down: the fraction favors the office. */
160	    static BigDecimal payment(BigDecimal amount) {
161	        return amount.setScale(WHOLE_G, RoundingMode.FLOOR);
162	    }
163	}
164	import java.math.BigDecimal;
